method below_zero(operations: seq<int>) returns (result: bool)
    requires operations != null
    ensures result == (exists i :: 0 <= i < |operations| && (|operations| > 0 && (Sum(operations[0..i]) < 0)))
{
    var balance := 0;
    var found := false;

    // Iterate through each operation in the sequence
    var i := 0;
    while i < |operations| && !found
        invariant 0 <= i <= |operations|
        invariant balance == Sum(operations[0..i])
        invariant !found => balance >= 0
    {
        balance := balance + operations[i];
        if balance < 0 {
            found := true;
        }
        i := i + 1;
    }

    result := found;
}
```

